#include "window.h"
#include <QtWidgets>
#include <QSqlQuery>
#include <QSqlError>
#include <set>

void Window::capcodes(){
 QDialog dialog(this);dialog.setWindowTitle("GESTION DES CAPCODES ENREGISTRÉS");dialog.resize(1350,650);auto layout=new QVBoxLayout(&dialog);
 layout->addWidget(new QLabel("Interprétation INHERIT = choix global. Dossier vide = chemin TXT hérité de 0.1.1. Conservation : historique SQLite uniquement, 0 = illimité."));
 auto search=new QLineEdit;search->setPlaceholderText("Rechercher un capcode, alias ou dossier…");layout->addWidget(search);
 auto table=new QTableWidget(0,15);table->setHorizontalHeaderLabels({"Capcode","Alias","Couleur","Actif","En bas","TXT hérité","Description","Dossier dédié","Nom fichier TXT","Quotidien","Interprétation","Historique (jours)","Dossier","Fichier hérité"});layout->addWidget(table);
 auto append=[&](QStringList values){
  bool sorting=table->isSortingEnabled();table->setSortingEnabled(false);int row=table->rowCount();table->insertRow(row);
  for(int col=0;col<12;++col){if(col==10){auto combo=new QComboBox;combo->addItems({"INHERIT","ALPHA","NUMERIC","AUTO"});combo->setCurrentText(values.value(col,"INHERIT"));table->setCellWidget(row,col,combo);continue;}auto cell=new QTableWidgetItem(values.value(col));if(col==3||col==4||col==9)cell->setCheckState(values.value(col).toInt()?Qt::Checked:Qt::Unchecked);table->setItem(row,col,cell);}
  auto folder=new QPushButton("Parcourir…");table->setCellWidget(row,12,folder);connect(folder,&QPushButton::clicked,&dialog,[&,folder]{int row=-1;for(int r=0;r<table->rowCount();++r)if(table->cellWidget(r,12)==folder)row=r;if(row<0)return;QString path=QFileDialog::getExistingDirectory(&dialog,"Dossier de ce capcode",table->item(row,7)->text());if(!path.isEmpty()){table->item(row,7)->setText(path);if(table->item(row,8)->text().isEmpty())table->item(row,8)->setText(table->item(row,0)->text()+".txt");}});
  auto file=new QPushButton("Choisir TXT…");table->setCellWidget(row,13,file);connect(file,&QPushButton::clicked,&dialog,[&,file]{for(int r=0;r<table->rowCount();++r)if(table->cellWidget(r,13)==file){QString path=QFileDialog::getSaveFileName(&dialog,"Fichier TXT hérité (ajout)",table->item(r,5)->text(),"Texte (*.txt)");if(!path.isEmpty()){table->item(r,5)->setText(path);table->item(r,7)->setText("");}break;}});table->setSortingEnabled(sorting);
 };
 QSqlQuery query("SELECT ric,alias,color,active,show_bottom,path,description,directory,filename,daily,interpretation,retention_days,voice_enabled FROM capcodes ORDER BY ric",db_);while(query.next()){QStringList values;values<<QString("%1").arg(query.value(0).toUInt(),7,10,QChar('0'));for(int col=1;col<13;++col)values<<query.value(col).toString();append(values);}query.finish();
 connect(search,&QLineEdit::textChanged,&dialog,[&](QString text){for(int r=0;r<table->rowCount();++r){bool matches=text.isEmpty();for(int c:{0,1,5,6,7,8})if(table->item(r,c)->text().contains(text,Qt::CaseInsensitive))matches=true;table->setRowHidden(r,!matches);}});
 auto rowValues=[&](int r){QStringList result;for(int c=0;c<12;++c){if(c==10)result<<qobject_cast<QComboBox*>(table->cellWidget(r,c))->currentText();else if(c==3||c==4||c==9)result<<QString::number(table->item(r,c)->checkState()==Qt::Checked);else result<<table->item(r,c)->text();}result<<QString::number(table->item(r,14)->checkState()==Qt::Checked);return result;};
 auto bar=new QHBoxLayout;layout->addLayout(bar);auto add=new QPushButton("Ajouter");auto remove=new QPushButton("Supprimer");auto import=new QPushButton("Importer JSON");auto exportButton=new QPushButton("Exporter JSON");auto retention=new QPushButton("Appliquer la conservation enregistrée…");for(auto button:{add,remove,import,exportButton,retention})bar->addWidget(button);
 connect(add,&QPushButton::clicked,&dialog,[&]{append({"0000000","","#47d7ff","1","1","","","","","0","INHERIT","0"});});connect(remove,&QPushButton::clicked,&dialog,[&]{if(table->currentRow()>=0)table->removeRow(table->currentRow());});
 connect(import,&QPushButton::clicked,&dialog,[&]{QString path=QFileDialog::getOpenFileName(&dialog,"Importer capcodes",{},"JSON (*.json)");if(path.isEmpty())return;QFile file(path);if(!file.open(QIODevice::ReadOnly)){QMessageBox::warning(&dialog,"Import",file.errorString());return;}QJsonParseError error;auto doc=QJsonDocument::fromJson(file.readAll(),&error);if(error.error!=QJsonParseError::NoError||!doc.isArray()){QMessageBox::warning(&dialog,"Import","JSON invalide");return;}for(auto value:doc.array()){QStringList row;for(auto cell:value.toArray())row<<cell.toString();if(row.size()==7)row<<""<<""<<"0"<<"INHERIT"<<"0";if(row.size()==12)row<<"0";if(row.size()==13)append(row);}});
 connect(exportButton,&QPushButton::clicked,&dialog,[&]{QString path=QFileDialog::getSaveFileName(&dialog,"Exporter capcodes",{},"JSON (*.json)");if(path.isEmpty())return;QJsonArray rows;for(int r=0;r<table->rowCount();++r){QJsonArray values;for(auto value:rowValues(r))values.append(value);rows.append(values);}QSaveFile file(path);if(!file.open(QIODevice::WriteOnly)){QMessageBox::warning(&dialog,"Export",file.errorString());return;}file.write(QJsonDocument(rows).toJson());if(!file.commit())QMessageBox::warning(&dialog,"Export",file.errorString());});
 connect(retention,&QPushButton::clicked,&dialog,[&]{QString condition="ric IN (SELECT ric FROM capcodes WHERE retention_days>0 AND julianday('now')-julianday(messages.timestamp)>retention_days)";QSqlQuery count("SELECT count(*) FROM messages WHERE "+condition,db_);count.next();int total=count.value(0).toInt();count.finish();if(!total){QMessageBox::information(&dialog,"Conservation","Aucun message historique à purger selon les options déjà enregistrées.");return;}if(QMessageBox::question(&dialog,"Purge de l'historique",QString("Supprimer %1 messages SQLite selon les durées enregistrées ? Les fichiers TXT sont conservés.").arg(total))!=QMessageBox::Yes)return;QSqlQuery purge(db_);if(!purge.exec("DELETE FROM messages WHERE "+condition))QMessageBox::warning(&dialog,"Purge",purge.lastError().text());refresh();});
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
 connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{
  std::set<uint> ids;for(int r=0;r<table->rowCount();++r){auto values=rowValues(r);bool valid=false;uint ric=values[0].toUInt(&valid);bool daysValid;int days=values[11].isEmpty()?0:values[11].toInt(&daysValid);if(values[11].isEmpty())daysValid=true;QString filename=values[8];if(!valid||ric>2097151||!ids.insert(ric).second||!QColor(values[2]).isValid()||!daysValid||days<0||days>365000||filename.contains(QRegularExpression("[\\\\/:*?\"<>|]"))||filename=="."||filename==".."){QMessageBox::warning(&dialog,"Validation","Capcode, couleur, nom de fichier ou durée invalide, ou adresse en double.");return;}}
  if(!db_.transaction())return;QSqlQuery clear(db_);if(!clear.exec("DELETE FROM capcodes")){db_.rollback();return;}
  for(int r=0;r<table->rowCount();++r){auto values=rowValues(r);QSqlQuery insert(db_);insert.prepare("INSERT INTO capcodes(ric,alias,color,active,show_bottom,path,description,directory,filename,daily,interpretation,retention_days,voice_enabled) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)");for(int c=0;c<13;++c)insert.addBindValue(values[c]);if(!insert.exec()){db_.rollback();QMessageBox::warning(&dialog,"SQLite",insert.lastError().text());return;}}
  if(!db_.commit()){db_.rollback();return;}dialog.accept();refresh();
 });connect(table,&QTableWidget::itemChanged,&dialog,[&](QTableWidgetItem* item){if(item->column()!=14)return;auto original=table->item(item->row(),0)->data(Qt::UserRole);if(!original.isValid())return;QSqlQuery update(db_);update.prepare("UPDATE capcodes SET voice_enabled=? WHERE ric=?");update.addBindValue(item->checkState()==Qt::Checked);update.addBindValue(original);if(!update.exec())technical(update.lastError().text());});dialog.exec();
}

void Window::journal(){
 QDialog dialog(this);dialog.setWindowTitle("JOURNAL TEXTE ET PROFILS");dialog.resize(1000,600);auto layout=new QVBoxLayout(&dialog);auto form=new QFormLayout;layout->addLayout(form);
 auto daily=new QCheckBox("Sous-dossiers quotidiens selon Europe/Brussels");daily->setChecked(daily_->isChecked());auto root=new QLineEdit(root_->text());auto name=new QLineEdit(profileName_->text());auto permanent=new QLineEdit(logPath_->text());form->addRow("Toute la Belgique",daily);form->addRow("Dossier principal",root);auto browse=new QPushButton("Parcourir le dossier principal…");form->addRow(browse);form->addRow("Nom du profil / sous-dossier",name);form->addRow("Fichier permanent (si quotidien désactivé)",permanent);auto choose=new QPushButton("Choisir un fichier permanent…");form->addRow(choose);
 connect(browse,&QPushButton::clicked,&dialog,[&]{QString path=QFileDialog::getExistingDirectory(&dialog,"Dossier principal TXT",root->text());if(!path.isEmpty())root->setText(path);});connect(choose,&QPushButton::clicked,&dialog,[&]{QString path=QFileDialog::getSaveFileName(&dialog,"Fichier TXT permanent",permanent->text(),"Texte (*.txt)");if(!path.isEmpty())permanent->setText(path);});
 layout->addWidget(new QLabel("Profils supplémentaires : fichiers en ajout UTF-8. Capcodes séparés par virgules ; liste vide = tous les messages acceptés."));auto table=new QTableWidget(0,5);table->setHorizontalHeaderLabels({"Profil","Fichier TXT","Capcodes","Actif","Parcourir"});table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);layout->addWidget(table);
 auto append=[&](QStringList values){int row=table->rowCount();table->insertRow(row);for(int c=0;c<4;++c){auto item=new QTableWidgetItem(values.value(c));if(c==3)item->setCheckState(values.value(c).toInt()?Qt::Checked:Qt::Unchecked);table->setItem(row,c,item);}auto button=new QPushButton("Parcourir…");table->setCellWidget(row,4,button);connect(button,&QPushButton::clicked,&dialog,[&,button]{for(int r=0;r<table->rowCount();++r)if(table->cellWidget(r,4)==button){auto path=QFileDialog::getSaveFileName(&dialog,"Fichier du profil",table->item(r,1)->text(),"Texte (*.txt)");if(!path.isEmpty())table->item(r,1)->setText(path);break;}});};
 QSqlQuery query("SELECT name,path,capcodes,enabled FROM profiles",db_);while(query.next()){QStringList row;for(int c=0;c<4;++c)row<<query.value(c).toString();append(row);}query.finish();
 auto bar=new QHBoxLayout;layout->addLayout(bar);auto add=new QPushButton("Ajouter profil");auto remove=new QPushButton("Supprimer profil");bar->addWidget(add);bar->addWidget(remove);connect(add,&QPushButton::clicked,&dialog,[&]{append({"Nouveau","","","0"});});connect(remove,&QPushButton::clicked,&dialog,[&]{if(table->currentRow()>=0)table->removeRow(table->currentRow());});
 auto buttons=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);connect(buttons,&QDialogButtonBox::accepted,&dialog,[&]{if(name->text().isEmpty()||name->text()=="."||name->text()==".."||name->text().contains(QRegularExpression("[\\\\/:*?\"<>|]"))){QMessageBox::warning(&dialog,"Profil","Nom de profil invalide");return;}if(!db_.transaction())return;QSqlQuery clear(db_);clear.exec("DELETE FROM profiles");for(int r=0;r<table->rowCount();++r){QSqlQuery insert(db_);insert.prepare("INSERT INTO profiles(name,path,capcodes,enabled) VALUES(?,?,?,?)");for(int c=0;c<3;++c)insert.addBindValue(table->item(r,c)->text());insert.addBindValue(table->item(r,3)->checkState()==Qt::Checked);if(!insert.exec()){db_.rollback();QMessageBox::warning(&dialog,"Profil",insert.lastError().text());return;}}if(!db_.commit()){db_.rollback();return;}root_->setText(root->text());profileName_->setText(name->text());logPath_->setText(permanent->text());daily_->setChecked(daily->isChecked());saveOptions();dialog.accept();});dialog.exec();
}
